SELECT id, product_name, brand, price, stock_qty, tags, ROW_NUMBER() OVER (PARTITION BY supplier_id ORDER BY stock_qty DESC, id) AS row_seq, SUM(price) OVER (PARTITION BY category, supplier_id ORDER BY price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_price, LAST_VALUE(cost) IGNORE NULLS OVER (ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost FROM products;
